  function getLangFlag(lang, size = null) {
    const imgStyle = size
      ? `width:${size}px;height:${Math.round(size * 0.6875)}px;object-fit:cover;border-radius:2px;`
      : `width:16px;height:11px;object-fit:cover;border-radius:2px;`;
    if (lang === 'ca' && FLAG_CA_B64) return `<img src="data:image/png;base64,${FLAG_CA_B64}" style="${imgStyle}">`;
    if (lang === 'eu' && FLAG_EU_B64) return `<img src="data:image/png;base64,${FLAG_EU_B64}" style="${imgStyle}">`;
    if (lang === 'gl' && FLAG_GL_B64) return `<img src="data:image/png;base64,${FLAG_GL_B64}" style="${imgStyle}">`;
    return LANG_FLAGS[lang] || '🌐';
  }

